import React from 'react';
import { Link } from 'react-router-dom';
import SeverityBadge from '../ui/SeverityBadge';
import StatusBadge from '../ui/StatusBadge';

export default function ReportsTable({ reports }) {
  return <div className="table-wrap"><table><thead><tr><th>CASE ID</th><th>CATEGORY</th><th>SEVERITY</th><th>STATUS</th><th>LOCATION</th><th>DATE REPORTED</th><th>ASSIGNED TO</th><th/></tr></thead><tbody>{reports.map(report => <tr key={report.id}><td><Link className="case-id" to={`/reports/${report.id}`}>{report.id}</Link></td><td>{report.category}</td><td><SeverityBadge severity={report.severity}/></td><td><StatusBadge status={report.status}/></td><td><span className="location-cell">⌖ {report.location}</span></td><td>{report.date}</td><td>{report.officer === 'Unassigned' ? <span className="unassigned">Unassigned</span> : report.officer}</td><td><Link className="row-more" to={`/reports/${report.id}`} aria-label={`Open ${report.id}`}>···</Link></td></tr>)}</tbody></table>{reports.length === 0 && <div className="empty">No reports match these filters.</div>}</div>;
}
